using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve the old property name.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF 9 uses only the raw key for the id property
            // instead of "Discriminator|Key". Existing documents use "Blog|1" format.
            entity.HasIdProperty(nameof(Blog.Id))
                  .HasIdJsonPropertyName("id");

            // Breaking change 3: Cosmos DB does not support indexes defined via
            // EF Core's HasIndex. This previously was silently ignored but now throws.
            // Removed: entity.HasIndex(b => b.Name);
            // Instead, configure indexing policy via Cosmos DB directly if needed.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

